export function audioCatalogueSectionCounts(entries = AUDIO_CATALOGUE) {
  const counts = {}
  for (const section of AUDIO_CATALOGUE_SECTIONS) counts[section.id] = 0
  for (const entry of entries) counts[entry.section] = (counts[entry.section] || 0) + 1
  return counts
}
